{"applicationStatus":{"type":"keyword","script":{"source":"if (doc['Data.service.applicationStatus.keyword'].size() > 0) {
  String status = doc['Data.service.applicationStatus.keyword'].value;
  if (status == 'PENDING_ASSIGNMENT') {
    emit('Pending Assignment');
  } else {
    emit(status);
  }
}"}}}

{"checklistDisplayName":{"type":"keyword","script":{"source":"if (params._source.containsKey('Data') && params._source.Data.containsKey('checklistName')) {
  String name = params._source.Data.checklistName;

  if (name == 'CDD_PERFORM_ASMT') {
    emit('CDD Perform Asmt');
  } else if (name == 'HFW_PERFORM_ASMT') {
    emit('HFW Perform Asmt');
  } else if (name == 'HF_ASMT') {
    emit('HF Assessment');
  } else if (name == 'ELIGIBILITY_ASSESSMENT') {
    emit('Eligibility Assessment');
  } else if (name == 'HF_RF_FEVER') {
    emit('Referred for Fever');
  } else if (name == 'HF_RF_DRUG_SE') {
    emit('Referred due to ADRs');
  } else if (name == 'HF_RF_SICK') {
    emit('Referred due to Sickness');
  } else if (name == 'CDD_PERFORMANCE') {
    emit('CDD Performance');
  } else if (name == 'HFW_RF_FEVER') {
    emit('HFW Referred for Fever');
  } else {
    // fallback for unmapped or new checklist names
    emit(name.replace('_', ' ')); 
  }
}
"}}}
